use super::prelude::*;

/// Attack twice for 5/6 and increase every combat Maul's damage by 2/3.
/// Source: v0.111.0 Models.Cards/Maul.cs.
pub(crate) fn play_maul(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Maul: Enemy-targeted");
    let dmg = current_damage(state);
    for _ in 0..2 {
        let alive = state
            .creatures
            .iter()
            .any(|c| c.id == t.0 && c.current_hp > 0);
        if !alive {
            break;
        }
        let _ = deal_damage_player_to_enemy(state, t, dmg);
    }
    let increase: i32 = if current_upgraded(state) { 3 } else { 2 };
    let cards = state
        .cards
        .iter()
        .filter(|card| {
            state.player.hand.contains(&card.uid)
                || state.player.draw.contains(&card.uid)
                || state.player.discard.contains(&card.uid)
                || state.player.exhaust.contains(&card.uid)
                || state.player.play.contains(&card.uid)
        })
        .map(|card| card.uid)
        .collect::<Vec<_>>();
    for uid in cards {
        if let Some(card) = state.cards.get_mut(uid.0.get() as usize - 1) {
            if card.card_id == CardId::Maul {
                card.base_damage = card.base_damage.saturating_add(increase);
            }
        }
    }
    EffectResult::Resolved
}
